export const calculateTranslateX = (minValue = -100, maxValue = 50, dx = 0) => {
  if (dx < minValue) {
    return minValue
  }
  if (dx > maxValue) {
    return maxValue
  }
  return dx
}

export const getFinalTranslateX = (dx, deleteWidth) => {
  if (dx < (deleteWidth / 3 + 1)) {
    return 0
  } else {
    return deleteWidth
  }
}
