import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useProfileContextValue } from '../../../context'
import { NOTIFICATION_ACTIONS } from '../actions'

export const useNotificationsServiceCall = (actionsCall = () => {}) => {
  const [notificationsState, dispatch] = useProfileContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback((payload = {}) => {
    callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [notificationsState, request]
}

export const useGetActivityNotificationsData = () => {
  return useNotificationsServiceCall(NOTIFICATION_ACTIONS.getActivityNotificationsAction)
}

export const useOtherNotificationsData = () => {
  return useNotificationsServiceCall(NOTIFICATION_ACTIONS.getOtherNotificationsAction)
}

export const useDeleteNotifications = () => {
  return useNotificationsServiceCall(NOTIFICATION_ACTIONS.deleteNotificationsAction)
}

export const useRemindCustomer = () => {
  const [state, dispatch] = useProfileContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = useCallback((payload = {}) => {
    callApi(NOTIFICATION_ACTIONS.remindCustomer({ body: payload }))
  }, [callApi])
  return [state, request]
}

export const useResetDependentState = () => {
  const [, dispatch] = useProfileContextValue()
  return (payload = {}) => {
    dispatch(NOTIFICATION_ACTIONS.resetNotificationState(payload))
  }
}
