import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react'
import { CustomText } from '../../../../../../../components'
import LazyLoader from '../../../../../../../components/LazyLoader'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { ITEM_NOT_FOUND } from '../../../../../../../images'
import { LANG_STRINGS } from '../../../../../../../lang'
import { useOtherNotificationsData, useDeleteNotifications, useResetDependentState } from '../../../../state/Notifications/hooks/useNotificationContext'
import { NotificationNotFound } from '../../container/index.style'
import NotificationCardWithDelete from '../NotificationCardWithDelete'
import ConfirmationModalV2 from '../../../../../../../components/ConfirmationModalV2'
import { useProfileContextValue } from '../../../../context'
import { NOTIFICATION_ACTIONS } from '../../../../state/Notifications/actions'
import NotificationBanner from '../../../../../Dashboard/components/NotificationBanner'

const OtherNotificationList = ({
  onRead, handleDeleteIconVisibility
}, parentRef) => {
  const notificationRef = useRef()
  const { resetError } = useResetError()
  const [, dispatch] = useProfileContextValue()
  const [{ otherNotificationsData = [] }, request] = useOtherNotificationsData()
  const [, deleteNotificationsRequest] = useDeleteNotifications()
  const [{ deleteNotificationStatus }] = useErrorContextValue()
  const [{ OTHER_NOTIFICATIONS_LOADER }] = useLoaderContextValue()
  const [notififcationIds, setNotificationIds] = useState([])
  const [confirmationModalVisible, setConfirmationModalVisible] = useState(false)
  const [showPushNotification, setShowPushNotification] = useState(false)
  const resetDependentState = useResetDependentState()
  const resetNotifications = useRef(resetDependentState)
  useImperativeHandle(parentRef, () => ({
    handleDeleteClick: () => setConfirmationModalVisible(true)
  }))

  useEffect(() => {
    const reset = resetNotifications.current
    request()
    return () => reset({
      otherNotificationsData: {}
    })
  }, [request])

  useEffect(() => {
    if (deleteNotificationStatus === 'success') {
      handleDeleteIconVisibility([])
      request()
      resetError(['deleteNotificationStatus'])
    }
  }, [
    deleteNotificationStatus, request,
    resetError, handleDeleteIconVisibility
  ])

  const handleDeleteNotification = (id) => {
    let updatedIds = notififcationIds
    if (notififcationIds.includes(id)) {
      updatedIds = notififcationIds.filter(existingId => existingId !== id)
    } else {
      updatedIds.push(id)
    }
    setNotificationIds([
      ...updatedIds
    ])
    handleDeleteIconVisibility(updatedIds)
  }

  const handleDeleteConfirmation = () => {
    deleteNotificationsRequest({
      notif_id_list: notififcationIds
    })
    setConfirmationModalVisible(false)
    dispatch(NOTIFICATION_ACTIONS.resetNotificationStore([
      'otherNotificationsData'
    ]))
  }

  const handlePushNotification = (data) => {
    const { description, extra_data: extraData } = data
    notificationRef.current = {
      description,
      image: extraData?.image,
      createdAt: data.created_at
    }
    setShowPushNotification(true)
  }

  return (
    <>
      {
        (otherNotificationsData?.data?.map && !!otherNotificationsData?.data?.length && otherNotificationsData.data
          ?.map(notification => ({ ...notification, provider_code: 'Sistem' }))
          ?.map((notification, index) => (
            <NotificationCardWithDelete
              key={index}
              data={notification}
              onRead={onRead}
              handleDelete={handleDeleteNotification}
              handlePushNotification={handlePushNotification}
            />
          ))) ||
          (OTHER_NOTIFICATIONS_LOADER === false && (
            <NotificationNotFound>
              <div>
                <img src={ITEM_NOT_FOUND} alt='' width='192px' />
              </div>
              <CustomText size='0.9em' color={AgentColorPallette.darkCharcoal}>
                {LANG_STRINGS.notificationNotFound}
              </CustomText>
            </NotificationNotFound>
          )) || null
      }
      {showPushNotification && (
        <NotificationBanner
          data={notificationRef.current}
          onClose={() => setShowPushNotification(false)}
        />
      )}
      {confirmationModalVisible && (
        <ConfirmationModalV2
          visible={confirmationModalVisible}
          title={LANG_STRINGS.deleteNotification}
          onCancel={() => setConfirmationModalVisible(false)}
          onOk={handleDeleteConfirmation}
          okButtonColor={AgentColorPallette.maroonRed}
          cancelButtonColor={AgentColorPallette.goldenText}
          okBtnId='delete-quote'
        >
          <div className='text-normal text-dark'>
            {LANG_STRINGS.sureYouWantToDeleteNotification}
          </div>
        </ConfirmationModalV2>
      )}
      <LazyLoader
        pageSize={10}
        request={request}
        responseData={otherNotificationsData}
        metaData={{
          page: otherNotificationsData?.meta_data?.page,
          total_pages: otherNotificationsData?.meta_data?.num_page
        }}
      />
    </>
  )
}
export default forwardRef(OtherNotificationList)
