import { ConfigUrl } from '../../../../../configs/url'

export const NOTIFICATION_ACTIONS = {
  ACTIVITY_NOTIFICATIONS_REQUEST: 'ACTIVITY_NOTIFICATIONS_REQUEST',
  ACTIVITY_NOTIFICATIONS: 'ACTIVITY_NOTIFICATIONS',
  OTHER_NOTIFICATIONS_REQUEST: 'OTHER_NOTIFICATIONS_REQUEST',
  OTHER_NOTIFICATIONS: 'OTHER_NOTIFICATIONS',
  REMIND_CUSTOMER_REQUEST: 'REMIND_CUSTOMER_REQUEST',
  REMIND_CUSTOMER: 'REMIND_CUSTOMER',
  RESET_NOTIFICATION_STATE: 'RESET_NOTIFICATION_STATE',
  DELETE_NOTIFICATION_REQUEST: 'DELETE_NOTIFICATION_REQUEST',
  DELETE_NOTIFICATION: 'DELETE_NOTIFICATION',
  RESET_NOTIFICATION_STORE: 'RESET_NOTIFICATION_STORE',
  getActivityNotificationsAction: (payload) => ({
    type: NOTIFICATION_ACTIONS.ACTIVITY_NOTIFICATIONS_REQUEST,
    payload: {
      query: payload,
      method: 'GET',
      url: ConfigUrl.getNotifications
    }
  }),
  getOtherNotificationsAction: (payload) => ({
    type: NOTIFICATION_ACTIONS.OTHER_NOTIFICATIONS_REQUEST,
    payload: {
      query: payload,
      method: 'GET',
      url: ConfigUrl.getOtherNotifications
    }
  }),
  remindCustomer: payload => ({
    type: NOTIFICATION_ACTIONS.REMIND_CUSTOMER_REQUEST,
    payload: {
      ...payload,
      method: 'POST',
      url: ConfigUrl.remindCustomer
    }
  }),
  resetNotificationState: (payload) => ({
    type: NOTIFICATION_ACTIONS.RESET_NOTIFICATION_STATE,
    payload
  }),
  deleteNotificationsAction: (payload) => ({
    type: NOTIFICATION_ACTIONS.DELETE_NOTIFICATION_REQUEST,
    payload: {
      body: payload,
      method: 'POST',
      url: ConfigUrl.deleteNotificationApi
    }
  }),
  resetNotificationStore: (payload = {}) => ({
    type: NOTIFICATION_ACTIONS.RESET_NOTIFICATION_STORE,
    payload
  })
}
