import { NotificationStyle } from './index.style'
import { Container } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang'
import Tabs from '../../../../../../components/Tabs'
import { TABS } from './content'
import { useLoaderContextValue, usePost } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useRef, useState } from 'react'
import { updateReadConfig } from './constatns'
import { useGetActivityNotificationsData, useOtherNotificationsData } from '../../../state/Notifications/hooks/useNotificationContext'

const Notifications = () => {
  const parentRef = useRef()
  const [current, setCurrent] = useState(TABS[0])
  const [{ ACTIVITY_NOTIFICATIONS_LOADER, REMIND_CUSTOMER_LOADER, OTHER_NOTIFICATIONS_LOADER, DELETE_NOTIFICATION_LOADER }] = useLoaderContextValue()
  const [{ activityNotificationsData = [] }] = useGetActivityNotificationsData()
  const [{ otherNotificationsData = [] }] = useOtherNotificationsData()
  const [readNotificationsIds, setReadNotificationsIds] = useState([])
  const [showDeleteIcon, setDeleteIconStatus] = useState(false)
  const CurrentComponent = current.component
  const [, updateReadRequest] = usePost(updateReadConfig)

  const showOtherLoader = DELETE_NOTIFICATION_LOADER || (OTHER_NOTIFICATIONS_LOADER && !otherNotificationsData?.data?.length)
  const showActivityLoader = ACTIVITY_NOTIFICATIONS_LOADER && !activityNotificationsData?.data?.length

  const handleRead = useCallback((id) => {
    setReadNotificationsIds(currentIds => [...currentIds, id])
  }, [])

  const callUpdateRead = useCallback(() => {
    if (readNotificationsIds.length) {
      updateReadRequest({
        notification_id: readNotificationsIds
      })
      setReadNotificationsIds(currentIds => currentIds.slice(readNotificationsIds.length))
    }
  }, [readNotificationsIds, updateReadRequest])

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      callUpdateRead()
    }, 2000)
    return () => clearTimeout(timeoutId)
  }, [callUpdateRead, readNotificationsIds])

  return (
    <Container
      title={LANG_STRINGS.notification}
      loader={!!(showActivityLoader || REMIND_CUSTOMER_LOADER || showOtherLoader)}
      displayBackButton
      hideBottomTabs
      showDeleteIcon={showDeleteIcon}
      onDeleteClick={() => parentRef.current.handleDeleteClick()}
      showOJKText
    >
      <NotificationStyle>
        <Tabs
          defaultTab={current}
          onClick={setCurrent}
          data={TABS}
          isSticky
        />
        <CurrentComponent ref={parentRef} onRead={handleRead} handleDeleteIconVisibility={(data) => setDeleteIconStatus(Boolean(data.length))} />
      </NotificationStyle>
    </Container>
  )
}
export default Notifications
