import { NOTIFICATION_ACTIONS } from './actions'

const reducer = (state = NOTIFICATION_ACTIONS, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case NOTIFICATION_ACTIONS.ACTIVITY_NOTIFICATIONS:
      return {
        ...state,
        activityNotificationsData: {
          meta_data: payload?.activityNotificationsData?.meta_data || state?.activityNotificationsData?.meta_data,
          data: [
            ...(state.activityNotificationsData?.data || []),
            ...(payload.activityNotificationsData?.data || [])
          ]
        }
      }
    case NOTIFICATION_ACTIONS.OTHER_NOTIFICATIONS:
      return {
        ...state,
        otherNotificationsData: {
          meta_data: payload?.otherNotificationsData?.meta_data || state?.otherNotificationsData?.meta_data,
          data: [
            ...(state.otherNotificationsData?.data || []),
            ...(payload.otherNotificationsData?.data || [])
          ]
        }
      }
    case NOTIFICATION_ACTIONS.DELETE_NOTIFICATION:
    case NOTIFICATION_ACTIONS.RESET_NOTIFICATION_STATE:
    case NOTIFICATION_ACTIONS.REMIND_CUSTOMER:
      return {
        ...state,
        ...payload
      }
    case NOTIFICATION_ACTIONS.RESET_NOTIFICATION_STORE: {
      const { payload } = action
      const modifyStore = {}
      payload.forEach(stateName => {
        modifyStore[stateName] = ''
      })
      return {
        ...state,
        ...modifyStore
      }
    }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
