import { useCallback, useEffect, useMemo, useRef } from 'react'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useHistory } from 'react-router'
import moment from 'moment'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { INFORMATION_NEW } from '../../../../../../../images'
import { useRemindCustomer } from '../../../../state/Notifications/hooks/useNotificationContext'
import ShowSnackbar from '../../../../../../../components/ShowNotification/index'
import { useGlobalContextValue } from '../../../../../../../contextProvider/GlobalContext'
import { useDraftPrevSteps, useDraftPrevStepsPropertyProtection } from '../../../../../../../state/commonState/hooks/useDraftPrevSteps'
import { CAR_PROTECTION, PROPERTY_PROTECTION } from '../../../../../../../constants/pkgCode'
import { useUpdateGlobal } from '../../../../../../../state/globalState/hooks/useGlobalContext'
import { checkIsLvAgent } from '../../../../../../../helpers/checkAgentTags'
import { NotificationCardStyle } from './index.style'
import { actions, getHumanizedDate } from './utility'

const INTERSECTION_OBSERVER_OPTIONS = {
  root: null,
  rootMargin: '0px',
  threshold: 1.0
}

const NotificationCard = (props) => {
  const {
    category,
    created_at: createdAt,
    notification,
    customer_data: customerData,
    extra_data: extraData = {},
    application_status: applicationStatus,
    provider_code: providerCode,
    provider_name: providerName,
    product_code: productCode,
    status
  } = props.data || {}

  const [{ agentDetails = {} }] = useUpdateGlobal()

  const [, remindCustomerRequest] = useRemindCustomer()
  const [{ productIconData = {} }] = useGlobalContextValue()
  const [{ REMIND_CUSTOMER_ERROR, remindCustomerStatus, remindCustomerErrorData }] = useErrorContextValue()
  const { resetError } = useResetError()
  const history = useHistory()
  const remindedNotifications = useRef({})
  const containerRef = useRef()
  const isMarkedReadCalled = useRef(false)
  const draftPrevSteps = useDraftPrevSteps()
  const draftPrevStepsProperty = useDraftPrevStepsPropertyProtection()

  const handleRemindButtonClick = useCallback((policyRefId) => {
    if (extraData.customer_reminder_time || remindedNotifications.current[policyRefId]) {
      const timer = extraData.customer_reminder_time || remindedNotifications.current[policyRefId]
      const duration = moment.duration(moment().diff(moment(timer)))
      const hrs = 23 - duration.hours()
      const mins = 59 - duration.minutes()
      const secs = 59 - duration.seconds()
      if (hrs > 0) {
        ShowSnackbar.success({
          visible: true,
          text: `Anda dapat mengingatkan pelanggan dalam ${hrs}:${mins}:${secs}`
        })
        return
      }
    }
    remindedNotifications.current[policyRefId] = new Date()
    remindCustomerRequest({ policy_or_draft_id: policyRefId })
  }, [remindCustomerRequest, extraData])

  const handlePaymentButtonClick = useCallback((policyId, productCode) => {
    if (productCode === CAR_PROTECTION) {
      history.push(`/payment/${productCode}/${policyId}`)
    } else {
      history.push(`${productCode}/packages/summary/${policyId}`)
    }
  }, [history])

  const handlePolicyIncomplete = useCallback((data) => {
    if (data.section && data.sub_section) {
      if (data.product_code === PROPERTY_PROTECTION) {
        draftPrevStepsProperty({
          section: data.section,
          subSection: data.sub_section,
          id: data.policy_id
        })
      } else {
        draftPrevSteps({
          section: data.section,
          subSection: data.sub_section,
          id: data.policy_id
        })
      }
    } else if (data.application_status === 'QUOTATION') {
      history.push(`/transactions/${data.policy_id}/details`)
    }
  }, [history, draftPrevSteps, draftPrevStepsProperty])

  const handlePushNotificationModal = useCallback((data) => {
    props.handlePushNotification(data.notification)
  }, [props])

  useEffect(() => {
    if (REMIND_CUSTOMER_ERROR && remindCustomerErrorData) {
      ShowSnackbar.error({
        text: remindCustomerErrorData.message,
        visible: true
      })
    }
    if (remindCustomerStatus === 'success') {
      ShowSnackbar.success({
        text: 'Pengingat terkirim.',
        visible: true
      })
    }
    return () => {
      resetError([
        'remindCustomerStatus',
        'remindCustomerErrorData'
      ])
    }
  }, [
    REMIND_CUSTOMER_ERROR,
    remindCustomerErrorData,
    remindCustomerStatus,
    resetError
  ])

  const handleObserver = useCallback((entities) => {
    const intersectionRatio = entities[0].intersectionRatio
    if (intersectionRatio > 0.9) {
      if (!isMarkedReadCalled.current && status !== 'READ') {
        props.onRead(notification.id)
        isMarkedReadCalled.current = true
      }
    }
  }, [notification, props, status])

  useEffect(() => {
    if (typeof props.onRead !== 'function') return
    const observer = new IntersectionObserver(
      handleObserver,
      INTERSECTION_OBSERVER_OPTIONS
    )
    observer.observe(containerRef.current)
    return () => {
      observer.disconnect()
    }
  }, [handleObserver, props])

  const isShowAction = useMemo(() => checkIsLvAgent(agentDetails), [agentDetails])

  return (
    <NotificationCardStyle ref={containerRef}>
      <div className='icon-container'>
        <img
          alt='Some text based on claim type'
          src={productIconData[productCode] || INFORMATION_NEW}
        />
      </div>
      <div className='text-container'>
        <div className='top-text-container'>
          <div className='provider-container'>
            <CustomText
              color={AgentColorPallette.fontDarkerGrey}
              size='11px'
              fontWeight='600'
            >
              {providerName || providerCode}
            </CustomText>
          </div>
          <div className='date-container'>
            <CustomText
              color={AgentColorPallette.borderGrey}
              size='11px'
              textAlign='right'
              fontWeight='600'
            >
              {getHumanizedDate(createdAt)}
            </CustomText>
          </div>
        </div>
        <div className='customer-container'>
          <CustomText
            weight={700}
            color={AgentColorPallette.regular}
            lineHeight='1.28'
            size='14px'
          >
            {notification.title}
          </CustomText>
        </div>
        <div className='text-container__notification-container'>
          <CustomText
            size='13px'
            color={AgentColorPallette.regular}
            lineHeight='1.33'
          >
            <pre>{notification.description}</pre>
          </CustomText>
        </div>
        <div className='action-container'>
          {
            isShowAction && actions[category] && actions[category]({
              handleRemindButtonClick: id => handleRemindButtonClick(id, notification),
              handlePaymentButtonClick,
              handlePolicyIncomplete,
              handlePushNotificationModal,
              data: props.data,
              applicationStatus,
              history
            })?.map((action, index) => {
              const handleClick = action.onClick
              if ((action.label === 'Ingatkan Pelanggan') && !customerData) return null
              return (
                <button
                  key={index}
                  className='action-button'
                  data-gtm-element-id={action.id}
                  onClick={handleClick}
                >
                  {action.label}
                </button>
              )
            })
          }
        </div>
      </div>
    </NotificationCardStyle>
  )
}
export default NotificationCard
