import moment from 'moment'
import { MICRO_PRODUCTS } from '../../../../../../../constants/pkgCode'

export const actions = {
  'payment-pending': ({ data, handleRemindButtonClick, history, handlePaymentButtonClick }) => {
    const remindToCustomer = {
      label: 'Ingatkan Pelanggan',
      id: 'remind-to-customer',
      onClick: () => handleRemindButtonClick(data.policy_id),
    }
    if (MICRO_PRODUCTS[data.product_code]) {
      return [remindToCustomer]
    }
    return [
      {
        label: 'bayar',
        id: 'quote-payment',
        onClick: () => handlePaymentButtonClick(data.policy_id, data.product_code),
      },
      remindToCustomer,
    ]
  },
  'incomplete-application': ({
    data,
    applicationStatus,
    handleRemindButtonClick,
    handlePolicyIncomplete,
  }) => {
    const actions = [
      {
        label: 'Lengkapi',
        id: '',
        onClick: () => handlePolicyIncomplete(data),
      },
    ]
    const remindToCustomer = {
      label: 'Ingatkan Pelanggan',
      id: 'remind-to-customer',
      onClick: () => handleRemindButtonClick(data.policy_id),
    }
    if (['QUOTATION'].includes(applicationStatus)) {
      actions.push(remindToCustomer)
    }
    if (MICRO_PRODUCTS[data.product_code]) {
      return [remindToCustomer]
    }
    return actions
  },
  'policy-renewal': ({ data, history }) => [
    {
      label: 'Perpanjang',
      id: 'quote-renewal',
      onClick: () => history.push(`/renewal/policy/details/mobil/${data.policy_id}`),
    },
  ],
  'policy-draft': ({ data, handlePolicyIncomplete, handleRemindButtonClick }) => {
    const remindToCustomer = []
    if (data.customer_data) {
      remindToCustomer.push({
        label: 'Ingatkan Pelanggan',
        id: 'remind-to-customer',
        onClick: () => handleRemindButtonClick(data.policy_id),
      })
    }
    return [
      {
        label: 'Lengkapi',
        id: '',
        onClick: () => handlePolicyIncomplete(data),
      },
      ...remindToCustomer,
    ]
  },
  'push-notifications': ({ data, handlePushNotificationModal }) => {
    return [
      {
        label: 'Lihat',
        id: '',
        onClick: () => handlePushNotificationModal(data),
      },
    ]
  },
  'new-policy-renewal': ({ data }) => {
    return [
      {
        label: 'Lengkapi',
        id: '',
        onClick: () => (window.location.href = data.notification.redirect_url),
      },
    ]
  },
}

export const getHumanizedDate = (date) => {
  const dateAsMoment = moment(date)
  const dayDiffernceFromToday = moment().diff(dateAsMoment, 'days')
  switch (dayDiffernceFromToday) {
    case 0:
      return `Hari ini, ${dateAsMoment.format('HH:mm')}`
    case 1:
      return `Kemarin, ${dateAsMoment.format('HH:mm')}`
    default:
      return dateAsMoment.format('DD-MM-YYYY, HH:mm')
  }
}
