import { useEffect, useRef, useState } from 'react'
import CustomCheckbox from '../../../../../../../components/CustomCheckbox'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import NotificationCard from '../NotificationCard'
import { NotificationCardWithDeleteWrapper } from './index.style'
import { calculateTranslateX, getFinalTranslateX } from './utility'

const NotificationCardWithDelete = ({ ...props }) => {
  const swipeableRef = useRef()
  const deleteRef = useRef()

  const [isCheckBoxClicked, setCheckBoxStatus] = useState(false)

  useEffect(() => {
    const _C = swipeableRef.current
    let x0 = null
    let locked = false
    let initialDx = 0
    const deleteWidth = deleteRef.current?.clientWidth || undefined

    const getCurrentTranslateX = () => {
      const translateXString = _C.style.transform.replace(/[^\d.]/g, '')
      if (!isNaN(Number(translateXString))) {
        return Number(translateXString)
      }
    }

    const unify = (e) => { return e.changedTouches ? e.changedTouches[0] : e }
    const lock = (e) => {
      if (e.cancellable) {
        e.preventDefault()
      }

      initialDx = getCurrentTranslateX()
      _C.classList.toggle('smooth', !(locked = true))
      x0 = unify(e).clientX
    }
    const move = (e) => {
      if (x0 || x0 === 0) {
        x0 = null
        _C.classList.toggle('smooth', !(locked = false))
        _C.style.transform = `translateX(${getFinalTranslateX(getCurrentTranslateX(), deleteWidth)}px)`
      }
    }
    function drag (e) {
      if (e.cancellable) {
        e.preventDefault()
      }
      if (locked) {
        const dx = unify(e).clientX - x0
        _C.style.transform = `translateX(${calculateTranslateX(0, deleteWidth, dx + initialDx)}px)`
      }
    };
    _C.addEventListener('mousedown', lock, false)
    _C.addEventListener('touchstart', lock, false)

    _C.addEventListener('mouseup', move, false)
    _C.addEventListener('touchend', move, false)
    _C.addEventListener('mousemove', drag, false)
    _C.addEventListener('touchmove', drag, false)
    return () => {
      _C.removeEventListener('mousedown', lock, false)
      _C.removeEventListener('touchstart', lock, false)
      _C.removeEventListener('mouseup', move, false)
      _C.removeEventListener('touchend', move, false)
      _C.addEventListener('mousemove', drag, false)
      _C.addEventListener('touchmove', drag, false)
    }
  }, [])

  const handleNotificationClick = () => {
    setCheckBoxStatus(prev => !prev)
    props.handleDelete(props.data.notification.id)
  }

  return (
    <>
      <NotificationCardWithDeleteWrapper>
        <CustomCheckbox
          color={AgentColorPallette.black}
          bgColor={AgentColorPallette.primary}
          isChecked={isCheckBoxClicked}
          onChange={handleNotificationClick}
          name='hardCopy'
          id='hardCopy'
          className='delete-btn text-white flex-container direction-column justify-center align-center text-xx-small text-extra-bold'
        />
        <div
          className='transaction-card-container'
          ref={swipeableRef}
        >
          <NotificationCard {...props} />
        </div>
      </NotificationCardWithDeleteWrapper>
    </>
  )
}

export default NotificationCardWithDelete
