import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useEffect, useRef } from 'react'
import { CustomText } from '../../../../../../../components'
import LazyLoader from '../../../../../../../components/LazyLoader'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { ITEM_NOT_FOUND } from '../../../../../../../images'
import { LANG_STRINGS } from '../../../../../../../lang'
import { useGetActivityNotificationsData, useResetDependentState } from '../../../../state/Notifications/hooks/useNotificationContext'
import { NotificationNotFound } from '../../container/index.style'
import NotificationCard from '../NotificationCard'

const ActivityNotificationList = () => {
  const [{ activityNotificationsData = [] }, request] = useGetActivityNotificationsData()
  const [{ ACTIVITY_NOTIFICATIONS_LOADER }] = useLoaderContextValue()
  const resetDependentState = useResetDependentState()
  const resetNotifications = useRef(resetDependentState)

  useEffect(() => {
    const reset = resetNotifications.current
    request()
    return () => reset({
      activityNotificationsData: {}
    })
  }, [request])

  return (
    <>
      {
        (activityNotificationsData?.data?.map && !!activityNotificationsData?.data?.length && activityNotificationsData.data.map((notification, index) => (
          <NotificationCard
            key={index}
            data={notification}
          />
        ))) || (ACTIVITY_NOTIFICATIONS_LOADER === false && (
          <NotificationNotFound>
            <div>
              <img src={ITEM_NOT_FOUND} alt='' width='192px' />
            </div>
            <CustomText size='0.9em' color={AgentColorPallette.darkCharcoal}>
              {LANG_STRINGS.notificationNotFound}
            </CustomText>
          </NotificationNotFound>
        )) || null
      }
      <LazyLoader
        pageSize={10}
        request={request}
        responseData={activityNotificationsData}
        metaData={{
          page: activityNotificationsData?.meta_data?.page,
          total_pages: activityNotificationsData?.meta_data?.num_page
        }}
      />
    </>
  )
}
export default ActivityNotificationList
